import{_ as t,o,c as n,a2 as i}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"Agent Identity & Behavior Audit Specification (T1.8 Specification)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/agent-audit.md","filePath":"specs/agent-audit.md","lastUpdated":null}'),a={name:"specs/agent-audit.md"};function d(r,e,s,c,l,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="agent-identity-behavior-audit-specification-t1-8-specification" tabindex="-1">Agent Identity &amp; Behavior Audit Specification (T1.8 Specification) <a class="header-anchor" href="#agent-identity-behavior-audit-specification-t1-8-specification" aria-label="Permalink to &quot;Agent Identity &amp; Behavior Audit Specification (T1.8 Specification)&quot;">​</a></h1><blockquote><p><strong>Version</strong>: v1.0.0 (T1.8 Specification: Agent Identity &amp; Behavior Audit)<br><strong>Status</strong>: <strong>Approved Specification</strong><br><strong>Scope</strong>: AgentPay Go Gateway Data Plane, Control Plane, Audit Stream &amp; Management Console<br><strong>Prerequisites</strong>: <a href="./multitenant-data-model">specs/multitenant-data-model.md</a>, <a href="./audit-events">specs/audit-events-spec.md</a></p></blockquote><hr><h2 id="_1-goals-boundaries" tabindex="-1">1. Goals &amp; Boundaries <a class="header-anchor" href="#_1-goals-boundaries" aria-label="Permalink to &quot;1. Goals &amp; Boundaries&quot;">​</a></h2><p>Three distinct requirements map to three distinct system capabilities and must not be conflated:</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Nature</th><th>Latency Requirement</th></tr></thead><tbody><tr><td>Visibility &amp; Troubleshooting: Tenants inspect what their Agents did</td><td>Querying &amp; timeline reconstruction</td><td>Near real-time (short delay acceptable)</td></tr><tr><td>Risk Control: Detect and block runaway Agents</td><td><strong>Enforcement</strong>, not post-hoc auditing</td><td><strong>Synchronous, in the request path</strong></td></tr><tr><td>Compliance &amp; Retention: Post-incident traceability and export</td><td>Integrity, retention, and export</td><td>Durable and verifiable</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Boundary Statement (Published in Public Documentation)</strong><br> The gateway can only audit an Agent&#39;s <strong>observable behaviors</strong> (requests, payments, policy decisions). It cannot inspect the Agent&#39;s internal reasoning chain or prove its subjective intent.</p></div><hr><h2 id="_2-core-design-principles" tabindex="-1">2. Core Design Principles <a class="header-anchor" href="#_2-core-design-principles" aria-label="Permalink to &quot;2. Core Design Principles&quot;">​</a></h2><ol><li><strong>One Event Stream, Three Consumers</strong>: All behaviors are emitted as canonical audit events. Visibility queries, anomaly detection, and compliance exports consume the same event stream rather than maintaining separate logs.</li><li><strong>Enforcement Never Depends on the Audit Pipeline</strong>: Budget limits, rate limits, allowlists, and kill-switch checks are evaluated <strong>synchronously in the request path</strong> using local and real-time counters—never waiting for asynchronous log analysis before blocking.</li><li><strong>Strict Separation of Observed vs. Declared Fields</strong>: <ul><li>What the gateway directly observes (<code>observed</code>) is objective fact (e.g., <code>agent_id</code> bound to the API Key, actual latency, upstream status code, deducted amount).</li><li>What the Agent self-reports via request headers (<code>declared</code>, such as <code>session_id</code>, <code>task_id</code>, <code>tool_name</code>) is untrusted, used solely for correlation and display, and <strong>strictly prohibited from authorization or billing decisions</strong>.</li></ul></li><li><strong>Metadata Only by Default</strong>: Request and response bodies are excluded from audit logs by default. Payload sampling must be explicitly enabled, redacted, assigned a separate retention period, and access-restricted.</li><li><strong>Append-Only</strong>: Audit events cannot be modified or deleted. Corrections are recorded by appending new audit events.</li></ol><hr><h2 id="_3-agent-entity-model" tabindex="-1">3. Agent Entity Model <a class="header-anchor" href="#_3-agent-entity-model" aria-label="Permalink to &quot;3. Agent Entity Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description &amp; Security Constraints</th></tr></thead><tbody><tr><td><code>agent_id</code></td><td>string (PK)</td><td>Format: <code>agt_...</code>, primary key</td></tr><tr><td><code>tenant_id</code></td><td>string (FK)</td><td>Tenant ownership; strict isolation boundary</td></tr><tr><td><code>project_id</code></td><td>string (FK)</td><td>Project ownership</td></tr><tr><td><code>name</code></td><td>string</td><td>Display name</td></tr><tr><td><code>status</code></td><td>string</td><td>Enum: <code>active</code> / <code>suspended</code> / <code>revoked</code></td></tr><tr><td>Key Binding</td><td>Association Table</td><td>One Agent may hold multiple API Keys; each API Key must belong to exactly one Agent</td></tr><tr><td>Policy Reference</td><td>JSONB / Association</td><td>Budget, rate limits, route allowlist, and risk rules (can inherit project defaults)</td></tr></tbody></table><h3 id="core-runtime-constraints" tabindex="-1">Core Runtime Constraints <a class="header-anchor" href="#core-runtime-constraints" aria-label="Permalink to &quot;Core Runtime Constraints&quot;">​</a></h3><ul><li><strong>Single Source of Truth for Identity</strong>: Every inbound request must resolve to an <code>agent_id</code> determined strictly by its cryptographic credential (API Key / signature)—<strong>never from client-supplied request headers</strong>.</li><li><strong>One-Click Kill Switch</strong>: When an Agent&#39;s status is set to <code>suspended</code> or its API Key is <code>revoked</code>, the gateway must reject subsequent requests within seconds (via instant invalidation notifications or RCU refresh); in-flight requests complete or release their holds according to existing state machine rules.</li></ul><hr><h2 id="_4-audit-event-schema-specification" tabindex="-1">4. Audit Event Schema Specification <a class="header-anchor" href="#_4-audit-event-schema-specification" aria-label="Permalink to &quot;4. Audit Event Schema Specification&quot;">​</a></h2><h3 id="_4-1-common-field-provenance-specification" tabindex="-1">4.1 Common Field Provenance Specification <a class="header-anchor" href="#_4-1-common-field-provenance-specification" aria-label="Permalink to &quot;4.1 Common Field Provenance Specification&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Provenance</th><th>Type &amp; Description</th></tr></thead><tbody><tr><td><code>event_id</code></td><td>Observed (<code>observed</code>)</td><td>Globally unique UUID/CUID serving as the write idempotency key</td></tr><tr><td><code>event_type</code></td><td>Observed (<code>observed</code>)</td><td>Event enum (see Section 4.2)</td></tr><tr><td><code>occurred_at</code></td><td>Observed (<code>observed</code>)</td><td>High-precision gateway timestamp (UTC)</td></tr><tr><td><code>tenant_id</code>, <code>project_id</code>, <code>agent_id</code></td><td>Observed (<code>observed</code>)</td><td>Resolved from the API Key; tamper-proof</td></tr><tr><td><code>request_id</code></td><td>Observed (<code>observed</code>)</td><td>Unified inbound trace ID assigned by the gateway</td></tr><tr><td><code>route_id</code>, <code>config_version</code></td><td>Observed (<code>observed</code>)</td><td>Matched route ID and active configuration fingerprint</td></tr><tr><td><code>actor</code></td><td>Observed (<code>observed</code>)</td><td><code>agent</code> / <code>admin</code> / <code>system</code></td></tr><tr><td><code>session_id</code>, <code>task_id</code>, <code>parent_request_id</code>, <code>tool_name</code></td><td><strong>Declared (<code>declared</code>)</strong></td><td>Self-reported by the Agent; strictly length-bounded (max 128 chars) and character-filtered against injection; <strong>completely optional</strong></td></tr><tr><td>Correlation IDs</td><td>Observed (<code>observed</code>)</td><td><code>payment_intent_id</code>, <code>settlement_id</code>, <code>fulfillment_id</code>, <code>hold_id</code></td></tr><tr><td><code>prev_hash</code>, <code>hash</code></td><td>Observed (<code>observed</code>)</td><td>Optional hash-chain tamper-evidence fingerprint (reserved interface)</td></tr></tbody></table><h3 id="_4-1-1-declared-fields-default-handling-security-invariants" tabindex="-1">4.1.1 Declared Fields Default Handling &amp; Security Invariants <a class="header-anchor" href="#_4-1-1-declared-fields-default-handling-security-invariants" aria-label="Permalink to &quot;4.1.1 Declared Fields Default Handling &amp; Security Invariants&quot;">​</a></h3><p>Declared fields are self-reported by clients via optional headers such as <code>X-Session-ID</code>, <code>X-Task-ID</code>, and <code>X-Tool-Name</code>.</p><table tabindex="0"><thead><tr><th>Processing Dimension</th><th>Client Supplies Declared Header</th><th>Client Omits Declared Header (Default)</th></tr></thead><tbody><tr><td><strong>Gateway Data Plane</strong></td><td>Whitelist-filtered and truncated to 128 characters before storing in the event</td><td>Extracted as <code>&quot;&quot;</code>; <strong>request proceeds normally without error</strong></td></tr><tr><td><strong>Billing &amp; Deductions</strong></td><td><strong>Strictly excluded</strong> from all authorization or billing decisions</td><td><strong>Completely unaffected</strong>; atomic transfer executes against the API Key&#39;s bound wallet</td></tr><tr><td><strong>Risk Control &amp; Circuit Breaking</strong></td><td>Synchronously enforces per-tx cap, 24h budget, and Kill Switch</td><td><strong>Completely unaffected</strong>; internal gateway counters enforce limits strictly</td></tr><tr><td><strong>Console Presentation</strong></td><td>Supports multi-call folding, aggregation, and session auditing by <code>session_id</code></td><td>Grouped under &quot;All Sessions&quot; and displayed as independent atomic requests in chronological order</td></tr><tr><td><strong>Timeline Badges</strong></td><td>Displays green <code>[Gateway Observed]</code> + yellow <code>[Self-Reported]</code> badges</td><td>Displays only the green <code>[Gateway Observed]</code> badge with zero loss of fidelity</td></tr></tbody></table><h3 id="_4-2-canonical-event-types" tabindex="-1">4.2 Canonical Event Types <a class="header-anchor" href="#_4-2-canonical-event-types" aria-label="Permalink to &quot;4.2 Canonical Event Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Domain</th><th>Meaning &amp; Included Payload</th></tr></thead><tbody><tr><td><code>agent.request</code></td><td>Request</td><td>Request arrival and outcome (HTTP status code, latency in ms, upstream payload size, request fingerprint hash)</td></tr><tr><td><code>agent.policy_decision</code></td><td>Policy</td><td>Policy verdict: <code>allow</code> / <code>deny</code>, matched rule ID, rejection reason code, config version</td></tr><tr><td><code>agent.spend</code></td><td>Payment</td><td>Fund operations: hold, capture, release, on-chain settlement (amount, asset, payment method)</td></tr><tr><td><code>agent.anomaly</code></td><td>Risk</td><td>Risk rule triggered: rule ID, safety threshold, observed metric value</td></tr><tr><td><code>agent.control</code></td><td>Control</td><td>Administrative action: suspend, resume, key revoke/rotate, budget adjustment (operator and reason)</td></tr><tr><td><code>agent.export</code></td><td>Compliance</td><td>Audit data export operation (exporter, filter criteria, exported row count)</td></tr></tbody></table><hr><h2 id="_5-risk-control-enforcement-layer" tabindex="-1">5. Risk Control (Enforcement Layer) <a class="header-anchor" href="#_5-risk-control-enforcement-layer" aria-label="Permalink to &quot;5. Risk Control (Enforcement Layer)&quot;">​</a></h2><h3 id="_5-1-v1-synchronous-policy-enforcement" tabindex="-1">5.1 v1 Synchronous Policy Enforcement <a class="header-anchor" href="#_5-1-v1-synchronous-policy-enforcement" aria-label="Permalink to &quot;5.1 v1 Synchronous Policy Enforcement&quot;">​</a></h3><ul><li><strong>Per-Agent Independent Budgets</strong>: Configurable 24-hour rolling window and monthly total spending caps per Agent, directly integrated with virtual wallet Holds.</li><li><strong>Per-Agent Rate Limiting</strong>: Fine-grained QPS/RPM limits per Agent to prevent infinite loops or high-frequency request storms.</li><li><strong>Route Allowlist</strong>: Strictly restricts an Agent to calling only authorized upstream APIs.</li><li><strong>Max Per Transaction (<code>Max Per Tx</code>)</strong>: Caps the maximum token expenditure for any single interaction.</li><li><strong>Sub-Second Kill Switch</strong>: When an administrator suspends an Agent or revokes an API Key, the gateway invalidates its cache immediately and blocks inbound requests within milliseconds.</li></ul><h3 id="_5-2-v1-x-anomaly-detection-alerting" tabindex="-1">5.2 v1.x Anomaly Detection &amp; Alerting <a class="header-anchor" href="#_5-2-v1-x-anomaly-detection-alerting" aria-label="Permalink to &quot;5.2 v1.x Anomaly Detection &amp; Alerting&quot;">​</a></h3><ul><li><strong>Behavioral Anomaly Rules</strong>: Traffic spikes, spend-rate surges, high-frequency consecutive denials, first-time access to rare routes, and unusual off-hours activity.</li><li><strong>Alert-Only by Default</strong>: Prevents false positives from interrupting production workflows; automatic blocking requires explicit administrator opt-in and a configured cooldown period.</li><li><strong>Notification Channels</strong>: Web Console notifications and Webhook callback pushes.</li></ul><hr><h2 id="_6-visibility-query-layer" tabindex="-1">6. Visibility (Query Layer) <a class="header-anchor" href="#_6-visibility-query-layer" aria-label="Permalink to &quot;6. Visibility (Query Layer)&quot;">​</a></h2><ol><li><strong>Agent Overview &amp; Directory</strong>: Status, recent call volume, total spend, and policy denial rate.</li><li><strong>Behavior Timeline</strong>: Displays the event stream chronologically and supports grouping workflow sessions by declared <code>session_id</code> / <code>task_id</code>.</li><li><strong>Multi-Dimensional Filtering</strong>: Time range, target route, HTTP status code, policy decision outcome, payment method, and event type.</li><li><strong>Drill-Down Inspection</strong>: One-click drill-down from a single request to its associated <code>payment_intent</code>, <code>settlement</code>, <code>hold</code>, <code>fulfillment</code>, and exact policy version evaluated.</li><li><strong>Multi-Tenant Permission Boundary</strong>: 100% invisible across tenants; any cross-tenant administrative operation must emit an independent high-severity audit event.</li></ol><hr><h2 id="_7-compliance-retention-export" tabindex="-1">7. Compliance Retention &amp; Export <a class="header-anchor" href="#_7-compliance-retention-export" aria-label="Permalink to &quot;7. Compliance Retention &amp; Export&quot;">​</a></h2><ol><li><strong>Append-Only Integrity</strong>: Audit tables permit only <code>INSERT</code> operations, with <code>UPDATE</code> and <code>DELETE</code> privileges revoked at the database level.</li><li><strong>Transactional Outbox</strong>: Events involving fund movements (<code>Hold</code>/<code>Capture</code>/<code>Release</code>) must be written atomically within the same database transaction as the ledger entry, guaranteeing that every deduction produces an audit record.</li><li><strong>Tiered Retention</strong>: <ul><li>Metadata events: Long-term retention (1+ year by default).</li><li>Payload samples (if explicitly enabled by the tenant): Short-term retention (7–30 days by default), governed by independent redaction policies and access controls.</li></ul></li><li><strong>Secure Export</strong>: Restricted to tenant administrators (CSV / JSONL formats); sensitive fields are automatically redacted prior to export, and every export operation is mandatorily recorded as an <code>agent.export</code> event.</li></ol><hr><h2 id="_8-threats-risk-mitigations" tabindex="-1">8. Threats &amp; Risk Mitigations <a class="header-anchor" href="#_8-threats-risk-mitigations" aria-label="Permalink to &quot;8. Threats &amp; Risk Mitigations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Threat Scenario</th><th>Risk Level</th><th>Gateway Mitigation Mechanism</th></tr></thead><tbody><tr><td>Spoofing <code>agent_id</code> via request headers</td><td><strong>Critical</strong></td><td>Gateway forcibly strips client-supplied <code>X-Agent-ID</code> headers and resolves identity solely from the API Key</td></tr><tr><td>Log injection via declared fields</td><td><strong>High</strong></td><td>Declared fields enforce character whitelisting and a 128-character limit, truncating or neutralizing malformed input</td></tr><tr><td>Credential leakage / Agent impersonation</td><td><strong>High</strong></td><td>Mitigated via IP allowlists, per-tx caps, and instant one-click Kill Switch</td></tr><tr><td>Propagation delay after suspension</td><td><strong>High</strong></td><td>Suspension and revocation propagate via in-memory RCU instant notifications rather than waiting for local TTL expiry</td></tr><tr><td>Cross-tenant unauthorized audit queries</td><td><strong>Critical</strong></td><td>Data access layer forcibly injects <code>tenant_id</code> predicates backed by Row-Level Security (RLS)</td></tr></tbody></table>',39)])])}const p=t(a,[["render",d]]);export{g as __pageData,p as default};
